import { balanceDue } from './payments.js';
import { daysBetween } from './dates.js';
import { lineTotal } from './invoices.js';
import { roundCents } from './money.js';

/**
 * Get overdue invoices sorted by days overdue (most overdue first).
 * @param {Array} invoices All invoices
 * @param {string} asOf Date in YYYY-MM-DD format
 * @returns {Array<{ number: string, customerId: string, dueDate: string, daysOverdue: number, due: number }>}
 */
export function overdueInvoices(invoices, asOf) {
  return invoices
    .filter(
      (inv) =>
        (inv.status === 'issued' || inv.status === 'partially_paid') &&
        inv.dueDate < asOf
    )
    .map((inv) => {
      const daysOverdue = daysBetween(inv.dueDate, asOf);
      return {
        number: inv.number,
        customerId: inv.customerId,
        dueDate: inv.dueDate,
        daysOverdue,
        due: balanceDue(inv),
      };
    })
    .sort((a, b) => b.daysOverdue - a.daysOverdue);
}

/**
 * Get VAT summary by rate for issued, partially_paid and paid invoices.
 * @param {Array} invoices All invoices
 * @returns {Array<{ rate: number, base: number, vat: number }>} Sorted by rate descending
 */
export function vatSummary(invoices) {
  const vatByRate = {};

  for (const invoice of invoices) {
    if (!['issued', 'partially_paid', 'paid'].includes(invoice.status)) {
      continue;
    }

    for (const line of invoice.lines) {
      const lineTot = lineTotal(line);
      const lineDiscount = roundCents((lineTot * (line.discountPercent || 0)) / 100);
      const base = lineTot - lineDiscount;
      const lineVAT = roundCents((base * line.vatRate) / 100);

      const rate = line.vatRate;
      if (!vatByRate[rate]) {
        vatByRate[rate] = { base: 0, vat: 0 };
      }
      vatByRate[rate].base += base;
      vatByRate[rate].vat += lineVAT;
    }
  }

  return Object.entries(vatByRate)
    .map(([rate, { base, vat }]) => ({
      rate: Number(rate),
      base,
      vat,
    }))
    .sort((a, b) => b.rate - a.rate);
}

/**
 * Calculate late fee for an invoice: 0.04% per day of balance due.
 * @param {{ status: string, dueDate: string }} invoice
 * @param {string} asOf Date in YYYY-MM-DD format
 * @returns {number} Late fee in cents, 0 if not overdue
 */
export function lateFee(invoice, asOf) {
  if (invoice.dueDate >= asOf) {
    return 0;
  }

  const daysOverdue = daysBetween(invoice.dueDate, asOf);
  const due = balanceDue(invoice);

  return roundCents((due * daysOverdue * 0.04) / 100);
}

