test('vatSummary calculates base (after discount) correctly', () => {
  const invoice = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 100, discountPercent: 20 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const result = vatSummary([issued]);

  const entry = result.find((r) => r.rate === firstProduct.vatRate);
  const expectedLineTotal = firstProduct.unitPrice * 100;
  const expectedDiscount = Math.round((expectedLineTotal * 20) / 100);
  const expectedBase = expectedLineTotal - expectedDiscount;

  assert.equal(entry.base, expectedBase);
});

