test('vatSummary groups by VAT rate', () => {
  const products = listProducts();
  const productsByRate = {};

  for (const p of products) {
    if (!productsByRate[p.vatRate]) {
      productsByRate[p.vatRate] = [];
    }
    productsByRate[p.vatRate].push(p);
  }

  const rates = Object.keys(productsByRate);
  if (rates.length >= 2) {
    const invoice = createInvoice({
      customerId: firstCustomer.id,
      issueDate: '2026-01-01',
      lines: rates.map((rate) => ({
        sku: productsByRate[rate][0].sku,
        qty: 10,
        discountPercent: 0,
      })),
    }).value;

    const issued = issueInvoice(invoice, []).value;
    const result = vatSummary([issued]);

    assert.equal(result.length, rates.length);
  }
});

test('vatSummary sorts by rate descending', () => {
